INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-24c4374ff40c', 'tim', 'outdoor', 'Descent magazine subscription', 'The UK''s premier caving magazine', 'A subscription to Descent magazine would be wonderful - it''s the main magazine covering caving, cave exploration, and underground adventures in the UK and beyond.', 'IconMap', 'https://wildplaces.co.uk/descent', NULL, '££', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-2b65993580d5', 'tim', 'outdoor', 'Old Descent magazines', 'Any issues from the last 15 years', 'I''d love to read back issues of Descent magazine from roughly 2010 onwards. Any copies you have lying around or can find second-hand would be really interesting to read.', 'IconMap', 'https://www.facebook.com/groups/cavinggearexchangeuk', NULL, '£', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-369ab686a67d', 'tim', 'outdoor', 'Spare caving light', 'A backup light for underground adventures', 'You can never have too many caving lights! A spare headtorch or helmet-mounted light suitable for caving would be very useful as a backup. Check the Caving Gear Exchange UK Facebook group for second-hand options.', 'IconBulb', 'https://www.facebook.com/groups/cavinggearexchangeuk', NULL, '££', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-3b4556c5afaf', 'tim', 'outdoor', 'Cheap, robust remote control car', 'Want to make me smile on Christmas day?', 'Not just when I open the present but for the rest of the day too! Find a cheap remote control car (second hand is absolutely fine) and make sure it has batteries or is charged and you''re good to go. Simple fun for everyone.', 'IconSteeringWheel', 'https://www.ebay.co.uk/sch/i.html?_nkw=remote+control+car+kids', NULL, '£', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-41479e7d8103', 'tim', 'outdoor', 'Heated socks', 'More heated socks please!', 'I love heated socks for keeping warm - can never have too many pairs. Link to follow.', 'IconSock', NULL, NULL, '££', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-4fe4e2f699d5', 'tim', 'food', 'Strong mature cheddar', 'Because I love cheese', 'All gift of cheddar cheese is welcome. No cheddar is too strong. Much more of a fan of cheddar than, say, fancy french cheeses', 'IconTools', 'https://www.barbers.co.uk/collections/all', NULL, '££', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-5033f2bddaea', 'tim', 'outdoor', 'Moorland Grit guidebook', 'A climbing guidebook that I won''t use', 'I don''t think I will climb anything in it, but it''s a guidebook of esoteric underclimbed, pieces of rock round Glossop. Rock probably best looked at rather than climbed, which is what makes the guidebook likely more fun than climbing them.', 'IconMap', 'https://www.amazon.co.uk/Moorland-Grit-bouldering-North-West-District/dp/1909461571', NULL, '££', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-58ed2acbe602', 'tim', 'tech', '170W ThinkPad Chargers', 'Must be 170W - less powerful chargers won''t work on my laptop', 'Rectangle-ended tip suitable for P50/P52 etc - second hand recommended. The link has many suitable ones that would all work.', 'IconDevices', 'https://www.ebay.co.uk/sch/i.html?_nkw=170w+p50+charger&_sacat=0&_from=R40&_sop=15&_blrs=spell_auto_correct', NULL, '££', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-66291f8ffd4e', 'tim', 'tech', 'New laptop keyboard', 'Replacement keyboard for my ThinkPad', 'A replacement keyboard for my laptop. Link to follow.', 'IconKeyboard', NULL, NULL, '££', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-6a1d971c8fb7', 'tim', 'tech', 'Laptop RAM', 'More memory for my laptop', 'Additional RAM to upgrade my laptop. Link to follow.', 'IconDevices', NULL, NULL, '££', 0);
