INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-7846893eae81', 'tim', 'tech', 'Contributions towards van bodywork', 'Help fix up the van', 'My van needs some bodywork repairs. Any contributions towards getting this done would be very welcome!', 'IconCar', NULL, NULL, '£££', 1);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-832b5f0bbe9c', 'tim', 'outdoor', 'Detailed field first aid kit', 'For Tim and Jen - PLEASE CONSULT BEFORE BUYING', 'We''d like a detailed, well-stocked field first aid kit with specific items. Please consult with Tim or Jen before buying this - don''t randomly buy a £2 first aid kit! We have particular requirements. Link to follow.', 'IconFirstAidKit', NULL, NULL, '££', 0);
