INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-904387bd697f', 'tim', 'tech', 'USB-C to USB-A cables', 'I need about 6 more', 'Second hand/preloved welcome!', 'IconDevices', 'https://www.ebay.co.uk/sch/i.html?_nkw=USB-C+to+USB-A+cables&_sacat=0&_from=R40&rt=nc&_udhi=6', NULL, '£', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-9a0a075b7c1b', 'tim', 'tech', '4TB 2.5" Internal Hard Drive', 'I''d like to be able to hold more photos in my laptop', 'I have a 2TB HDD, and a 4TB disk would let me do more work and hold more photos of James! The one linked will fit my laptop.', 'IconDevices', 'https://www.ebuyer.com/2264757-crucial-bx500-4tb-2-5-inch-internal-ssd-ct4000bx500ssd1', NULL, '£££', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-a50ba72cb141', 'tim', 'tech', 'Basic headphones', 'I can never have enough 3.5mm headphones with microphones.', 'Please not bluetooth ones. The ones linked are my favourite model, but all headphones gratefully recieved.', 'IconDevices', 'https://www.ebay.co.uk/itm/195579022728', NULL, '£', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-a88115c7b1e3', 'tim', 'outdoor', 'Technical Gore-tex waterproof jacket', 'To keep me warm and dry in the rain.', 'I have an old goretex ME jacket, but it''s starting to become a bit like swiss cheese - something not known for waterproofness. I''ve put a link to a ME Pro Shell in Large - but there are many other suitable jackets.', 'IconMountain', 'https://www.ebay.co.uk/sch/i.html?_nkw=Mountain+Equipment+Pro+shell&_sacat=0&_from=R40&rt=nc&Chest%2520Size=L&_dcat=181358', NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-b7e826b8bbb5', 'tim', 'books', 'Wild Spirit by Helen Lloyd', 'My friend wrote this book and I''d love to read it.', 'Unsolicited book recommendation: her other books are fantastic. Sadly I already own them.', 'IconBook', 'https://amzn.to/3YXBItR', NULL, '£', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-bce1c7757fe6', 'tim', 'tech', 'AI credits', 'Credits for Claude AI - which I use daily', 'I find myself finding Anthropic''s Claude API extremely helpful and taking up some of my money. It helps me do things faster, better than ever before and I''m finding it extremely helpful. I sometimes spend about $2 per day on it, and it easily is delivering £10 of value to me each time. Money towards it would be warmly welcomed.', 'IconRobot', 'https://www.anthropic.com/pricing#anthropic-api', NULL, '££', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-c48531c3249d', 'tim', 'support', 'Babysitting', 'Time to help look after James - even 30 minutes makes a difference', 'Having someone watch James, even for a short while, gives us a chance to do essential tasks or have a brief rest. This gift of time is incredibly valuable to us. No special skills needed - just patience and enthusiasm!', 'IconHeart', NULL, NULL, 'FREE', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-cb5d26fbdfdc', 'tim', 'support', 'Sentimental items', 'Photos or mementos of times we''ve shared together', 'I''d love photos of us doing things together, or items that help us remember shared experiences. Could be recent or from years ago - anything that might remind me of shared memories.', 'IconHeart', NULL, NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-d1ba29ab7593', 'tim', 'home', 'Chopped Firewood', 'We have a small stove ', 'As much as I''d love some massive pieces of tree, without a chainsaw and appropriate knowledge, any firewood would be best in stove size portions.', 'IconTools', 'https://pearsonfuels.co.uk/product-category/local-shop/kiln-dried-logs/', NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-de9733318cd2', 'tim', 'support', 'A stress-free Christmas', 'Would be dreamy', 'We all can try', 'IconHeart', 'https://www.youtube.com/watch?v=dQw4w9WgXcQ', NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-e5c41ca5e751', 'tim', 'outdoor', 'Drysuit (Large/XL)', 'For year-round kayaking comfort', 'A waterproof drysuit (size Large or XL) would let me kayak in colder weather without getting cold. Look for reputable brands like Palm, Kokatat, or Gul. Second-hand in good condition is perfectly acceptable!', 'IconSwimming', 'https://www.ebay.co.uk/sch/i.html?_nkw=drysuit+large+xl+kayaking&_sacat=0&LH_ItemCondition=4&rt=nc', NULL, '£££', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-efc2c9c8a1be', 'tim', 'food', 'Lidl or Aldi Penne', 'The cheap pasta that just hits different', 'Yes, this is partly a joke gift. But also, there''s something about the cheap Lidl/Aldi penne that just works better than fancy pasta. I will genuinely eat and enjoy this. Multiple bags welcome!', 'IconTools', NULL, NULL, '£', 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe4-f081c2a82b99', 'jen', 'food', 'Povey''s Gluten Free Staffordshire Oatcakes', '6 pack of traditional GF oatcakes', 'Gluten Free Traditional Staffordshire Oatcakes from Povey''s. Call 01782 511799 or email info@poveysoatcakes.com to order.', 'IconCake', 'https://poveysoatcakes.com/product/6-gluten-free-traditional-staffordshire-oatcakes/', NULL, NULL, 0);
