INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe5-14958a90539f', 'jen', 'home', 'Micro Toastie Maker', 'Already bought (£19) - contributions welcome', 'I''ve already bought myself a micro toastie maker for £19 - it was a bargain! Contributions towards the cost are welcome.', 'IconToolsKitchen', NULL, 19, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe5-1c491a7289af', 'jen', 'home', 'Contribution to a new television', 'Our TV could do with an upgrade (~£200 total)', 'We''re thinking about getting a new television. It would cost about £200. Any contributions towards this would be gratefully received!', 'IconDeviceTv', NULL, 200, NULL, 1);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe5-2169e0539ca0', 'jen', 'clothing', 'Warm tracksuit (sweatshirt material)', 'Cosy loungewear for relaxing at home', 'Looking for a warm tracksuit in soft sweatshirt material. No tight ankle cuffs please - I don''t like them! Sweatshirt style preferred. Darker colours preferred. The key thing is it needs to be warm and soft.', 'IconJacket', NULL, NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe5-2a2f83d0a479', 'jen', 'clothing', 'Cosy jumpers', 'Simple, warm jumpers in various necklines', 'Looking for straightforward, warm jumpers - nothing fancy or fussy. I don''t like roll necks, but boat necks, v-necks, and round necks are all fine. Square shoulders look good too. Please nothing with a seam from armpit to the neck. Just simple and cosy!', 'IconJacket', NULL, NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe5-30d2332b1da7', 'jen', 'food', 'Nice gluten-free eating/cake experience', 'A GF meal out, food delivery, or treats', 'Whether it''s a voucher for a restaurant with good gluten-free options, or some quality GF food or cake to enjoy at home - a nice gluten-free eating experience would be lovely. Jen loves Gluten Free Kitchen Stockport - get them to send her something!', 'IconToolsKitchen', 'https://www.facebook.com/p/Gluten-Free-Kitchen-Stockport-61554087298652/', NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe5-3981a8b2415b', 'jen', 'wellbeing', 'Money towards massages', 'To help with baby-carrying muscle tension', 'Carrying and caring for a growing baby puts a lot of strain on shoulders, back, and arms. Massages help manage this physical stress and provide some relaxation time. Contributions towards professional massage sessions would be greatly appreciated.', 'IconHeartHandshake', NULL, NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe5-4603993e2964', 'jen', 'home', 'House plant pots', 'So I can put plants I already have, in pots in the house', 'I already have some pleasing plants, and one things preventing me from displaying them in my home is lack of plant pots. Perhaps you can help?', 'IconPlant', 'https://www.ebay.co.uk/sch/i.html?_nkw=House+plant+pots&_sacat=0&_from=R40&_trksid=p4432023.m570.l1313', NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe5-4ae14f0b4cd5', 'jen', 'home', 'Glass food storage containers with lids', 'CHUNGG Glass Prep Containers - set of 10', 'Glass meal prep containers with lids, suitable for microwave, oven, fridge and dishwasher. Set of 10 in 1040ML & 370ML sizes.', 'IconBox', 'https://www.amazon.co.uk/dp/B0FN7GR4PW', NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe5-5189d3612204', 'jen', 'support', 'Time with helpers for sorting/organizing', 'To help sort out things around the house', 'I''d benefit from helpful people to work with me on doing things round the house one day when James is at nursery and I''m off work.', 'IconUsers', NULL, NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894c-7aa3-8fe5-5beb309f81b4', 'jen', 'wellbeing', 'Krupnik Plum Liquor (500ml)', 'My preferred liquor with a pleasing taste', 'Available from Food Plus (£12.89) or Polish shops. 30% ABV, 500ml bottles. The more bottles the better! A refined recipe combining delicate sweetness of plums with a gentle alcohol warmth.', 'IconGlass', 'https://uk.foodplus.eu/en_GB/p/Krupnik-Plum-Vodka-Alc.30-500ml/23647', NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894d-7aa3-8fe5-6748afa7c6a1', 'james', 'learning', 'Story books', 'James loves being read to!', 'James really enjoys story books. Please buy books that he would enjoy being read, or that you would enjoy reading to him. They don''t need to be educational - fun is absolutely fine! Picture books, silly stories, adventure tales - all welcome. We already have loads, so perhaps check with us before you buy!', 'IconBook', 'https://www.ebay.co.uk/sch/i.html?_nkw=childrens+picture+books+bundle', NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894d-7aa3-8fe5-6c9f4a3cee69', 'james', 'outdoor', 'Small buoyancy aid for swimming', 'Smallest size if possible', 'It''s entirely possible that James use this for a while, but he''d like it so he can one day go near water and on boats.', 'IconSwimming', 'https://www.watersportswarehouse.co.uk/products/gul-dartmouth-100n-lifejacket', NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894d-7aa3-8fe5-7778d094f72f', 'james', 'food', 'Grapes or plums', 'For stockings or generally', 'James loves grapes and plums! Perfect for stockings or as a healthy snack gift.', 'IconMoodSmile', NULL, NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894d-7aa3-8fe5-7dc363b72d12', 'james', 'learning', 'The Great British Colouring Book', 'A special colouring book created by top British cartoonists', 'Created by over 50 cartoonists including Terry Gilliam and Quentin Blake, this book features more than 100 original cartoons showing different aspects of British culture. While it might be for when he''s a bit older, it''s a meaningful gift with a great story behind it - originally created for children arriving in the UK.', 'IconBook', 'https://cartoonmuseum.shop/products/book-the-great-british-colouring-book', NULL, NULL, 0);
INSERT INTO gifts (id, recipient_id, category_key, name, short_description, long_description, icon, url, price, price_indicator, allow_multiple) VALUES ('019ae68b-894d-7aa3-8fe5-81535002b695', 'james', 'active', 'Little table with two chairs', 'A small table and chairs set for James', 'A little table with two chairs - wood preferred. Second hand in good condition is perfect!', 'IconArmchair', 'https://www.ebay.co.uk/sch/i.html?_nkw=kids+table+chairs+oak', NULL, '££', 0);
