INSERT INTO faq_answers (id, faq_id, person, requirements) VALUES ('019ae68b-894d-7aa3-8fe6-36f346fef76e', '019ae68b-894d-7aa3-8fe6-2ea588104131', 'Jen', 'Coeliac - strictly no gluten/wheat/barley (even traces). Eats all meat and fish. Not a fan of sprouts.');
